1|import "server-only";
2|import { buildPrompt } from "@/core/images";
3|import type { ImageStyle, StyleBook } from "@/core/image-style";
4|import { buildChapterPrompt, chapterPanels } from "@/core/panels";
5|import { classifyInputOf } from "@/core/fingerprint";
6|import type { ImageKind, Scene } from "@/core/types";
7|import { chapterReference, getBookmap } from "./bookmap-prompt";
8|
9|// Final prompt assembly, shared by the route and pregen so a stored
10|// page always matches what the route would generate for its key.
11|export function buildFinalPrompt(args: {
12|  kind: ImageKind;
13|  passageText: string;
14|  sceneTitle: string;
15|  sceneClip: string;
16|  chapterPanels?: { description: string }[];
17|  style?: ImageStyle;
18|  book?: StyleBook;
19|  reference?: string;
20|}): string {
21|  const base =
22|    args.kind === "chapter"
23|      ? buildChapterPrompt({
24|          chapterTitle: args.sceneTitle,
25|          panels: args.chapterPanels ?? [],
26|          style: args.style,
27|          book: args.book,
28|        })
29|      : buildPrompt({
30|          kind: args.kind,
31|          passageText: args.passageText,
32|          sceneTitle: args.sceneTitle,
33|          sceneClip: args.sceneClip,
34|          style: args.style,
35|          book: args.book,
36|        });
37|  const reference = args.reference ?? "";
38|  return reference ? `${base} ${reference}` : base;
39|}
40|
41|// Chapter prompt exactly as the route builds it: panels over the
42|// chapter's scenes plus the chapter reference block. Pregen calls this
43|// so first-write-wins Blob pages match the route byte for byte.
44|export function buildPregenChapterPrompt(args: {
45|  book: {
46|    id: string;
47|    title: string;
48|    author: string;
49|    textVersion: string;
50|    chapters: { ch: number; title: string }[];
51|  };
52|  scenes: Scene[];
53|  ch: number;
54|  style?: ImageStyle;
55|}): string {
56|  const chapterScenes = args.scenes.filter((s) => s.ch === args.ch);
57|  const reference = chapterReference({
58|    bookmap: getBookmap(args.book.id, args.book.textVersion, classifyInputOf(args.scenes, args.book.textVersion)),
59|    sceneIds: chapterScenes.map((s) => s.id),
60|    ch: args.ch,
61|  });
62|  return buildFinalPrompt({
63|    kind: "chapter",
64|    passageText: "",
65|    sceneTitle: args.book.chapters.find((c) => c.ch === args.ch)?.title ?? "",
66|    sceneClip: "",
67|    chapterPanels: chapterPanels(chapterScenes),
68|    style: args.style,
69|    book: { id: args.book.id, title: args.book.title, author: args.book.author },
70|    reference,
71|  });
72|}

