29|function toResponse(res: ImageResponse): { json: ImageResponse; status: number } {
30|  if (res.status === "ready" || res.status === "pending") return { json: res, status: 200 };
31|  const status =
32|    res.code === "bad_request" ? 400 : res.code === "quota" ? 429 : res.code === "human" ? 403 : 503;
33|  return { json: res, status };
34|}
35|
36|export interface ImagesHandlerDeps {
37|  env?: ImageEnv;
38|  kv?: KV;
39|  store?: ImageStore;
40|  generate?: ImageGenerator;
41|  fetchFn?: typeof fetch;
42|}
43|
44|export async function handleImagesPost(req: Request, deps: ImagesHandlerDeps = {}): Promise<Response> {
45|  if (rejectsCrossSite(req.headers, req.url)) {
46|    return Response.json(
47|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
48|      { status: 400 },
49|    );
50|  }
51|
52|  const capped = await readBodyCapped(req, MAX_IMAGE_BODY_BYTES);
53|  if (!capped.ok) {
54|    return Response.json(
55|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
56|      { status: capped.reason === "too_large" ? 413 : 400 },
57|    );
58|  }
59|
60|  let parsed: ImageRequest;
61|  try {
62|    parsed = parseImageRequest(JSON.parse(capped.text));
63|  } catch (e) {
64|    if (e instanceof ImageStyleError) {
65|      return Response.json(
66|        { status: "error", code: "bad_request", message: MSG_STYLE } satisfies ImageResponse,
67|        { status: 400 },
68|      );
69|    }
70|    return Response.json(
71|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
72|      { status: 400 },
73|    );
74|  }
75|
76|  // Pictures and chapter panels serve every ready shelf book. Unknown
77|  // or not-ready ids stop here, before env, quota, or spend are touched.
78|  if (!isReadyBookId(parsed.bookId)) {
79|    return Response.json(
80|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
81|      { status: 400 },
82|    );
83|  }
84|
85|  let env = deps.env;
86|  if (!env) {
87|    try {
88|      env = readImageEnv();
89|    } catch (e) {
90|      const message = e instanceof Error ? e.message : "";
91|      const prefix = "missing image env:";
92|      const names = message.startsWith(prefix) ? message.slice(prefix.length).trim() : "";
93|      console.warn(`image env missing: ${names}`);
94|      return Response.json(
95|        { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
96|        { status: 503 },
97|      );
98|    }
99|  }
100|
101|  try {
102|    const { book, scenes } = await loadBookData(parsed.bookId);
103|    try {
104|      validateAgainstBook(
105|        parsed,
106|        {
107|          id: book.id,
108|          textVersion: book.textVersion,
109|          paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
110|          sceneIds: new Set(scenes.map((s) => s.id)),
111|          chapters: new Set(book.chapters.map((c) => c.ch)),
112|        },
113|      );
114|    } catch {
115|      return Response.json(
116|        { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
117|        { status: 400 },
118|      );
119|    }
120|
121|    const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
122|    const req0 = parsed;
123|    const sceneOf =
124|      req0.kind === "chapter"
125|        ? undefined
126|        : scenes.find((s) =>
127|            req0.kind === "passage" ? req0.n >= s.start_n && req0.n <= s.end_n : s.id === req0.sceneId,
128|          );
129|    // A selection never leaves its starting scene; a lone paragraph
130|    // keeps the bare pN key.
131|    if (parsed.kind === "passage" && parsed.endN !== undefined) {
132|      const end = Math.min(parsed.endN, sceneOf?.end_n ?? parsed.endN);
133|      const { endN: _dropped, ...single } = parsed;
134|      parsed = end <= parsed.n ? single : { ...parsed, endN: end };
135|    }
136|    const passageTexts: string[] = [];
137|    if (parsed.kind === "passage") {
138|      for (let n = parsed.n; n <= (parsed.endN ?? parsed.n); n++) passageTexts.push(byN.get(n) ?? "");
139|    }
140|    const sceneParas = sceneOf
141|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
142|      : [];
143|    // Chapter content comes from the frozen book: the chapter title plus
144|    // the panel groups over that chapter's scenes. The client sends the
145|    // chapter number only, so no client text reaches the prompt.
146|    const chapterNo = parsed.kind === "chapter" ? parsed.ch : null;
147|    const content: ImageContent =
148|      chapterNo !== null
149|        ? {
150|            passageText: "",
151|            sceneTitle: book.chapters.find((c) => c.ch === chapterNo)?.title ?? "",
152|            sceneClip: "",
153|            chapterPanels: chapterPanels(scenes.filter((s) => s.ch === chapterNo)),
154|          }
155|        : {
156|            passageText: parsed.kind === "passage" ? passageTexts.join(" ") : "",
157|            sceneTitle: sceneOf?.title ?? "",
158|            sceneClip: sceneParas.map((p) => p.text).join(" "),
159|          };
160|
161|    // Bookmap reference details for the prompt (delimited block).
162|    // A missing bookmap yields "" and the prompt stays as it was.
163|    const bookmap = getBookmap(book.id, book.textVersion, classifyInputOf(scenes, book.textVersion));
164|    let reference = "";
165|    if (parsed.kind === "passage") {
166|      const start = parsed.n;
167|      const end = parsed.endN ?? parsed.n;
168|      reference = passageReference({
169|        bookmap,
170|        sceneIds: scenes.filter((s) => s.start_n <= end && s.end_n >= start).map((s) => s.id),
171|        selectedText: passageTexts.join(" "),
172|        ch: sceneOf?.ch ?? 0,
173|      });
174|    } else if (parsed.kind === "scene" && sceneOf) {
175|      reference = passageReference({
176|        bookmap,
177|        sceneIds: [sceneOf.id],
178|        selectedText: content.sceneClip,
179|        ch: sceneOf.ch,
180|      });
181|    } else if (parsed.kind === "chapter" && chapterNo !== null) {
182|      reference = chapterReference({
183|        bookmap,
184|        sceneIds: scenes.filter((s) => s.ch === chapterNo).map((s) => s.id),
185|        ch: chapterNo,
186|      });
187|    }
188|
189|    const cookieValue = parseAnonCookie(req.headers.get("cookie"));
190|    let anonId = cookieValue ? verifyAnonCookie(cookieValue, env.sessionSecret) : null;
191|    let setCookie: string | null = null;
192|    if (!anonId) {
193|      const issued = issueAnonId(env.sessionSecret);
194|      anonId = issued.id;
195|      setCookie = serializeAnonCookie(issued.value);
196|    }
197|
198|    const ip = clientIp(req.headers);
199|    const humanOut: { setCookie?: string } = {};
200|    const res = await orchestrate(parsed, {
201|      kv: deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken),
202|      store: deps.store ?? createBlobStore(),
203|      generate: deps.generate ?? createMetaClient(env.metaKey),
204|      env,
205|      content: {
206|        ...content,
207|        reference,
208|        book: { id: book.id, title: book.title, author: book.author },
209|      },
210|      ip,
211|      anonId,
212|      day: utcDay(),
213|      sceneId: sceneOf?.id ?? "",
214|      // On the miss path only; cache hits return before this is read.
215|      human: {
216|        cookieHeader: req.headers.get("cookie"),
217|        token: parsed.turnstileToken,
218|        ip,
219|        turnstileSecret: env.turnstileSecret,
220|        turnstileSiteKey: env.turnstileSiteKey,
221|        sessionSecret: env.sessionSecret,
222|        fetchFn: deps.fetchFn,
223|      },
224|      humanOut,
225|    });
226|
227|    const { json, status } = toResponse(res);
228|    const headers = new Headers();
229|    if (setCookie) headers.append("Set-Cookie", setCookie);
230|    if (humanOut.setCookie) headers.append("Set-Cookie", humanOut.setCookie);
231|    return Response.json(json, { status, headers });
232|  } catch (e) {
233|    console.error(`image request failed: ${errorTag(e)}`);
234|    return Response.json(
