1|// Pregenerate chapter comic pages through the same key, index, and
2|// spend counters as the route. Each miss spends one image, so dry-run
3|// first and run only with the owner's say-so.
4|//
5|// Run: npx tsx --conditions=react-server scripts/pregen-chapters.ts
6|//   [--ch all|1,2] [--style skins|<id>] [--dry-run]
7|import { readFileSync } from "node:fs";
8|import type { BookPayload } from "../server/books";
9|import { createBlobStore } from "../server/images/blob";
10|import { usable } from "../server/guard/env";
11|import { createMetaClient } from "../server/images/meta";
12|import { createRestKV } from "../server/guard/kv";
13|import { utcDay } from "../server/guard/request";
14|import { reserveSpend } from "../server/guard/spend";
15|import { imageCostMicro, imageKey, indexKeyFor } from "../core/images";
16|import { SKIN_DEFAULT_IMAGE_STYLE, parseStyleChoice } from "../core/image-style";
17|import type { ImageStylePresetId } from "../core/image-style";
18|import { buildPregenChapterPrompt } from "../server/images/final-prompt";
19|
20|const SKIN_STYLE_IDS = [
21|  ...new Set(
22|    Object.values(SKIN_DEFAULT_IMAGE_STYLE).filter(
23|      (v): v is ImageStylePresetId => v !== undefined,
24|    ),
25|  ),
26|];
27|
28|const USAGE = `usage: pregen-chapters.ts [--ch all|1,2] [--style skins|<id>] [--dry-run]
29|  --ch all          every chapter (default)
30|  --ch 1,2          only these chapters
31|  --style skins     every skin default style (default)
32|  --style <id>      one of: ${SKIN_STYLE_IDS.join(", ")}
33|  --dry-run         list cached and planned pages plus expected USD, spend nothing`;
34|
35|function flag(name: string): boolean {
36|  return process.argv.includes(name);
37|}
38|
39|function opt(name: string): string | undefined {
40|  const i = process.argv.indexOf(name);
41|  const v = i >= 0 ? process.argv[i + 1] : undefined;
42|  return v === undefined || v.startsWith("--") ? undefined : v;
43|}
44|
45|function usd(micro: number): string {
46|  return `$${(micro / 1_000_000).toFixed(2)}`;
47|}
48|
49|function parseCapUsd(raw: string | undefined, fallback: number): number {
50|  if (raw === undefined || raw.trim() === "") return fallback;
51|  const value = Number(raw);
52|  return Number.isFinite(value) && value >= 0 ? value : fallback;
53|}
54|
55|async function main(): Promise<void> {
56|  if (flag("--help") || flag("-h")) {
57|    console.log(USAGE);
58|    return;
59|  }
60|  const dryRun = flag("--dry-run");
61|
62|  // Names only on failure, never values.
63|  const rawUrl = usable(process.env.UPSTASH_REDIS_REST_URL) ?? usable(process.env.KV_REST_API_URL);
64|  const rawToken =
65|    usable(process.env.UPSTASH_REDIS_REST_TOKEN) ?? usable(process.env.KV_REST_API_TOKEN);
66|  const url = rawUrl?.startsWith("https://") ? rawUrl : undefined;
67|  const missing = [
68|    url ? null : "UPSTASH_REDIS_REST_URL|KV_REST_API_URL",
69|    rawToken ? null : "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN",
70|    usable(process.env.BLOB_READ_WRITE_TOKEN) ? null : "BLOB_READ_WRITE_TOKEN",
71|    usable(process.env.META_API_KEY) ? null : "META_API_KEY",
72|  ].filter((m): m is string => m !== null);
73|  if (missing.length > 0) {
74|    console.error(`missing image env: ${missing.join(",")}`);
75|    process.exit(1);
76|  }
77|  const capMicro = Math.round(parseCapUsd(process.env.SPEND_CAP_USD, 10) * 1_000_000);
78|  const dailyCapMicro = Math.round(parseCapUsd(process.env.DAILY_SPEND_CAP_USD, 2) * 1_000_000);
79|
80|  // Read the JSON directly: server/books imports next/navigation, which
81|  // cannot load outside Next (it broke this script after #122).
82|  const read = (f: string): unknown => JSON.parse(readFileSync(`data/books/oz/${f}`, "utf8"));
83|  const book = read("book.json") as BookPayload["book"];
84|  const { scenes } = read("analysis.json") as { scenes: BookPayload["scenes"] };
85|  const known = new Map(book.chapters.map((c) => [c.ch, c.title]));
86|  const chArg = opt("--ch") ?? "all";
87|  const wantCh =
88|    chArg === "all"
89|      ? [...known.keys()].sort((a, b) => a - b)
90|      : chArg.split(",").map((s) => Number(s.trim()));
91|  for (const ch of wantCh) {
92|    if (!Number.isInteger(ch) || !known.has(ch)) {
93|      console.error(`unknown chapter: ${chArg} (book has ${[...known.keys()].sort((a, b) => a - b).join(",")})`);
94|      process.exit(1);
95|    }
96|  }
97|  const styleArg = opt("--style") ?? "skins";
98|  const wantStyles =
99|    styleArg === "skins" ? SKIN_STYLE_IDS : SKIN_STYLE_IDS.filter((id) => id === styleArg);
100|  if (wantStyles.length === 0) {
101|    console.error(`unknown style: ${styleArg} (one of: skins, ${SKIN_STYLE_IDS.join(", ")})`);
102|    process.exit(1);
103|  }
104|
105|  const kv = createRestKV(url as string, rawToken as string);
106|  const store = createBlobStore();
107|  const generate = createMetaClient(process.env.META_API_KEY as string);
108|  const day = utcDay();
109|  const cost = imageCostMicro();
110|  let cached = 0;
111|  let generated = 0;
112|  let failed = 0;
113|  let planned = 0;
114|
115|  for (const ch of wantCh) {
116|    for (const styleId of wantStyles) {
117|      const style = parseStyleChoice({ preset: styleId });
118|      const key = imageKey({
119|        kind: "chapter",
120|        bookId: book.id,
121|        textVersion: book.textVersion,
122|        ch,
123|        reachedCh: ch,
124|        ...(style === undefined ? {} : { style }),
125|      });
126|      const indexKey = indexKeyFor(key);
127|      const hit = await kv.get(indexKey);
128|      if (hit) {
129|        cached++;
130|        console.log(`ch ${ch} ${styleId} cached ${hit}`);
131|        continue;
132|      }
133|      const blobUrl = await store.findUrl(key);
134|      if (blobUrl) {
135|        try {
136|          await kv.set(indexKey, blobUrl);
137|        } catch {
138|          // The file exists; the next run backfills again.
139|        }
140|        cached++;
141|        console.log(`ch ${ch} ${styleId} cached ${blobUrl}`);
142|        continue;
143|      }
144|      if (dryRun) {
145|        planned++;
146|        console.log(`ch ${ch} ${styleId} planned`);
147|        continue;
148|      }
149|      const spent = await reserveSpend(kv, {
150|        amountMicro: cost,
151|        day,
152|        spendCapMicro: capMicro,
153|        dailySpendCapMicro: dailyCapMicro,
154|      });
155|      if (!spent.ok) {
156|        console.log(
157|          spent.which === "total"
158|            ? `Stopped: spend cap reached at ch ${ch} ${styleId}, reserve refunded.`
159|            : `Stopped: daily spend cap reached at ch ${ch} ${styleId}, reserve refunded.`,
160|        );
161|        process.exitCode = 1;
162|        return;
163|      }
164|      const refund = (): Promise<void> => spent.reservation.release();
165|      let bytes: Uint8Array;
166|      try {
167|        bytes = await generate.generate(buildPregenChapterPrompt({ book, scenes, ch, style }));
168|      } catch {
169|        await refund();
170|        failed++;
171|        console.log(`ch ${ch} ${styleId} failed -`);
172|        continue;
173|      }
174|      let saved: string;
175|      try {
176|        saved = await store.save(key, bytes);
177|      } catch {
178|        await refund();
179|        failed++;
180|        console.log(`ch ${ch} ${styleId} failed -`);
181|        continue;
182|      }
183|      try {
184|        await kv.set(indexKey, saved);
185|      } catch {
186|        // The file exists; the next run backfills the index.
187|      }
188|      generated++;
189|      console.log(`ch ${ch} ${styleId} generated ${saved}`);
190|    }
191|  }
192|
193|  if (dryRun) {
194|    console.log(`Planned: ${planned} pages (${cached} cached), expected ${usd(planned * cost)}.`);
195|  } else {
196|    console.log(
197|      `Total: ${cached + generated + failed} pages (${cached} cached, ${generated} generated, ${failed} failed). Spent ${usd(generated * cost)}.`,
198|    );
199|  }
200|}
201|
202|try {
203|  await main();
204|} catch (e) {
205|  console.error(`pregen failed: ${e instanceof Error ? e.message : "unknown"}`);
206|  process.exit(1);
207|}

