1|// Preloaded classics for the home library grid. Ready favorites first,
2|// the rest in manifest order, so new books need no UI change.
3|import manifest from "../data/library.json";
4|
5|export interface LibraryBook {
6|  id: string;
7|  title: string;
8|  author: string;
9|  year: number;
10|  words: number;
11|  gutenbergId: number;
12|  status: "ready";
13|  favorite?: boolean;
14|  cover: string;
15|  coverAlt: string;
16|}
17|
18|function isBook(value: unknown): value is LibraryBook {
19|  if (typeof value !== "object" || value === null) return false;
20|  const b = value as Record<string, unknown>;
21|  return (
22|    typeof b.id === "string" &&
23|    typeof b.title === "string" &&
24|    typeof b.author === "string" &&
25|    typeof b.year === "number" &&
26|    typeof b.words === "number" &&
27|    typeof b.gutenbergId === "number" &&
28|    b.status === "ready" &&
29|    (b.favorite === undefined || typeof b.favorite === "boolean") &&
30|    typeof b.cover === "string" &&
31|    b.cover.startsWith("/art/") &&
32|    typeof b.coverAlt === "string" &&
33|    b.coverAlt.length > 0
34|  );
35|}
36|
37|export function loadLibrary(raw: unknown = manifest): LibraryBook[] {
38|  if (!Array.isArray(raw)) throw new Error("library manifest must be an array");
39|  const books = raw.map((entry) => {
40|    if (!isBook(entry)) throw new Error(`bad library entry: ${JSON.stringify(entry)}`);
41|    return entry;
42|  });
43|  return [...books].sort((a, b) => Number(b.favorite ?? false) - Number(a.favorite ?? false));
44|}
45|
46|// 250 words/min, rounded to the minute.
47|export function readingMinutes(words: number): string {
48|  const total = Math.max(1, Math.round(words / 250));
49|  const hours = Math.floor(total / 60);
50|  const mins = total % 60;
51|  if (hours === 0) return `About ${mins} min`;
52|  if (mins === 0) return `About ${hours} h`;
53|  return `About ${hours} h ${mins} min`;
54|}
55|
56|export const library: LibraryBook[] = loadLibrary();

