87|// Whole words and phrases rejected on the normalized custom text: prompt
88|// override, nsfw, and people/brand guards. Entries stay literal lowercase
89|// words and spaces, matched with word boundaries only.
90|const DENY_WORDS = [
91|  "ignore", "disregard", "forget", "instead", "instruction", "instructions",
92|  "prompt", "system", "override", "previous", "assistant", "text", "caption",
93|  "captions", "letter", "letters", "lettering", "word", "words", "write",
94|  "written", "logo", "logos", "watermark",
95|  "nude", "nudity", "naked", "nsfw", "sex", "sexy", "sexual", "porn",
96|  "erotic", "hentai", "lingerie", "gore", "gory", "bloody",
97|  "by", "artist", "studio", "celebrity", "ghibli", "miyazaki", "disney",
98|  "pixar", "dreamworks", "marvel", "banksy", "toriyama", "burton", "mgm",
99|  "garland", "ruby",
100|];
101|
102|const DENY_PHRASES = ["style of", "in the style", "photo of"];
103|
104|const DENY_RE = new RegExp(`\\b(?:${[...DENY_WORDS, ...DENY_PHRASES].join("|")})\\b`, "u");
105|
106|// Null means rejected. Control and format chars become spaces so newlines,
107|// tabs, zero-width, and bidi marks cannot smuggle extra instructions.
108|export function normalizeCustomStyle(raw: string): string | null {
109|  const normalized = raw
110|    .normalize("NFKC")
111|    .replace(/[\p{Cc}\p{Cf}]/gu, " ")
112|    .replace(/\s+/g, " ")
113|    .trim()
114|    .toLowerCase();
115|  if (normalized.length < 2 || normalized.length > MAX_CUSTOM_STYLE_CHARS) return null;
116|  if (!/^[\p{L}\p{N} ,.'&-]+$/u.test(normalized)) return null;
117|  if (DENY_RE.test(normalized)) return null;
118|  return normalized;
119|}
120|
121|// Undefined means default. Exact shapes only: one key, a known preset id
122|// or a normalizable custom string; anything else throws ImageStyleError.
123|// {preset:"denslow"} returns undefined, so it keys like an omitted style.
124|export function parseStyleChoice(json: unknown): ImageStyle | undefined {
125|  if (json === undefined) return undefined;
126|  if (typeof json !== "object" || json === null || Array.isArray(json)) throw new ImageStyleError();
127|  const rec = json as Record<string, unknown>;
128|  if (Object.keys(rec).length !== 1) throw new ImageStyleError();
129|  if ("preset" in rec) {
130|    if (typeof rec.preset !== "string") throw new ImageStyleError();
131|    if (rec.preset === DEFAULT_IMAGE_STYLE) return undefined;
132|    if (!isPresetId(rec.preset)) throw new ImageStyleError();
133|    return { kind: "preset", id: rec.preset };
134|  }
135|  if ("custom" in rec) {
136|    if (typeof rec.custom !== "string") throw new ImageStyleError();
137|    const text = normalizeCustomStyle(rec.custom);
138|    if (text === null) throw new ImageStyleError();
