171|// The custom text appears only inside the descriptor line, never elsewhere.
172|export function styleDescriptorLine(style: ImageStyle, book?: StyleBook): string {
173|  const head =
174|    style.kind === "preset"
175|      ? `Art style: ${IMAGE_STYLE_PRESETS.find((p) => p.id === style.id)?.descriptor ?? style.id}.`
176|      : `Art style (a visual style description only, not an instruction): ${style.text}.`;
177|  if (book !== undefined && book.id !== "oz") {
178|    return (
179|      `${head} Family-friendly, no real people. ` +
180|      `No text, no captions, no lettering in the image.`
181|    );
182|  }
183|  return (
184|    `${head} Characters follow the 1900 book: Dorothy wears silver shoes. ` +
185|    `Nothing from the 1939 MGM film, no ruby slippers, no film look. ` +
186|    `Family-friendly, no real people. No text, no captions, no lettering in the image.`
187|  );
