190|      await release();
191|      return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
192|    }
193|
194|    const quota = await takeDualQuota(deps.kv, keys, {
195|      limit: DAILY_IMAGE_LIMIT,
196|      ttlSec: QUOTA_TTL_SEC,
