204|    // Both caps apply only to requests paid with our key. The future
205|    // BYOK path must skip these reserves and check its own key instead.
206|    const spent = await reserveSpend(deps.kv, {
207|      amountMicro: imageCostMicro(),
208|      day: deps.day,
209|      spendCapMicro: deps.env.spendCapMicro,
210|      dailySpendCapMicro: deps.env.dailySpendCapMicro,
211|    });
