226|          kind: req.kind,
227|          passageText: deps.content.passageText,
228|          sceneTitle: deps.content.sceneTitle,
229|          sceneClip: deps.content.sceneClip,
230|          chapterPanels: deps.content.chapterPanels,
231|          style: req.style,
232|          book: deps.content.book,
