269|      }
270|      await releaseSpendOnce();
271|      await refundQuotaOnce();
272|      await release();
273|      console.error(`image store failed: ${errorTag(e)}`);
274|      return { status: "error", code: "unavailable", message: MSG_FAILED };
275|    }
276|  } catch (e) {
277|    await releaseSpendOnce();
278|    await refundQuotaOnce();
279|    await release();
280|    console.error(`image request failed: ${errorTag(e)}`);
281|    return { status: "error", code: "unavailable", message: MSG_FAILED };
282|  }
283|}
284|
285|function captionFor(req: ImageRequest, content: ImageContent): string {
286|  return buildCaption({
287|    kind: req.kind,
288|    sceneTitle: content.sceneTitle,
289|    passageText: content.passageText,
290|  });
