307|// In-memory KV for tests. Expiries are checked against Date.now.
308|export function createMemoryKV(): KV & { clear(): void } {
309|  const values = new Map<string, string>();
310|  const expiresAt = new Map<string, number>();
311|  function live(key: string): boolean {
312|    const until = expiresAt.get(key);
313|    if (until !== undefined && Date.now() >= until) {
314|      values.delete(key);
315|      expiresAt.delete(key);
316|      return false;
317|    }
318|    return true;
319|  }
320|  function num(key: string): number {
321|    return Number(values.get(key) ?? "0");
322|  }
323|  return {
324|    async get(key: string): Promise<string | null> {
325|      if (!live(key)) return null;
326|      return values.get(key) ?? null;
327|    },
328|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
329|      if (live(key) && values.has(key)) return false;
330|      values.set(key, value);
331|      expiresAt.set(key, Date.now() + exSec * 1000);
332|      return true;
333|    },
334|    async set(key: string, value: string): Promise<void> {
335|      values.set(key, value);
336|      expiresAt.delete(key);
337|    },
338|    async incr(key: string): Promise<number> {
339|      const next = num(key) + 1;
340|      values.set(key, String(next));
341|      return next;
342|    },
343|    async incrBy(key: string, by: number): Promise<number> {
344|      const next = num(key) + by;
345|      values.set(key, String(next));
346|      return next;
347|    },
348|    async decr(key: string): Promise<number> {
349|      const next = num(key) - 1;
350|      values.set(key, String(next));
351|      return next;
352|    },
353|    async decrBy(key: string, by: number): Promise<number> {
354|      const next = num(key) - by;
355|      values.set(key, String(next));
356|      return next;
357|    },
358|    async expire(key: string, sec: number): Promise<void> {
359|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
360|    },
361|    async releaseIfToken(key: string, token: string): Promise<boolean> {
362|      if (!live(key)) return false;
363|      if (values.get(key) !== token) return false;
364|      values.delete(key);
365|      expiresAt.delete(key);
366|      return true;
367|    },
368|    clear(): void {
369|      values.clear();
370|      expiresAt.clear();
371|    },
372|  };
