46|  explicit: StyleChoice | undefined,
47|  skin: string | undefined,
48|): StyleChoice {
49|  if (explicit !== undefined) return explicit;
50|  if (skin !== undefined && Object.hasOwn(SKIN_DEFAULT_IMAGE_STYLE, skin)) {
51|    const id = SKIN_DEFAULT_IMAGE_STYLE[skin];
52|    if (id !== undefined) return { preset: id };
53|  }
54|  return { preset: DEFAULT_IMAGE_STYLE };
