1|// Chapter panels: the one grouping rule for captions and the chapter
2|// page prompt. Pure: no env reads, no network. The client sends only the
3|// chapter number; descriptions come from trusted server-side summaries.
4|import { clipText, styleLine } from "./images";
5|import type { ImageStyle, StyleBook } from "./image-style";
6|import { panelCaption } from "./reader";
7|
8|export interface ChapterPanelGroup {
9|  sceneIds: string[];
10|  caption: string;
11|  description: string;
12|}
13|
14|// Up to 6 panels. Past 6 scenes, adjacent scenes merge into 6
15|// contiguous groups, sizes as even as possible, larger groups first.
16|export function chapterPanels(scenes: { id: string; summary: string }[]): ChapterPanelGroup[] {
17|  if (scenes.length === 0) return [];
18|  const groups = Math.min(scenes.length, 6);
19|  const base = Math.floor(scenes.length / groups);
20|  const extra = scenes.length % groups;
21|  const out: ChapterPanelGroup[] = [];
22|  let at = 0;
23|  for (let g = 0; g < groups; g++) {
24|    const slice = scenes.slice(at, at + base + (g < extra ? 1 : 0));
25|    at += slice.length;
26|    const first = slice[0];
27|    if (!first) continue;
28|    out.push({
29|      sceneIds: slice.map((s) => s.id),
30|      caption: panelCaption(first.summary),
31|      description: slice.map((s) => s.summary).join(" "),
32|    });
33|  }
34|  return out;
35|}
36|
37|// Fixed grid: panels per row, top to bottom.
38|const PANEL_ROWS: Record<number, number[]> = {
39|  1: [1],
40|  2: [1, 1],
41|  3: [1, 2],
42|  4: [2, 2],
43|  5: [2, 1, 2],
44|  6: [2, 2, 2],
45|};
46|
47|export function panelRows(count: number): number[] {
48|  const rows = PANEL_ROWS[count];
49|  if (!rows) throw new RangeError(`panel count ${count} has no layout`);
50|  return [...rows];
51|}
52|
53|export const PANEL_DESC_CHARS = 300;
54|
55|export function buildChapterPrompt(args: {
56|  chapterTitle: string;
57|  panels: { description: string }[];
58|  style?: ImageStyle;
59|  book?: StyleBook;
60|}): string {
61|  const rows = panelRows(args.panels.length);
62|  const panelsWord = args.panels.length === 1 ? "panel" : "panels";
63|  const rowsWord = rows.length === 1 ? "row" : "rows";
64|  const layout = rows.map((count, i) => `row ${i + 1} has ${count}`).join(", ");
65|  return (
66|    `Chapter "${args.chapterTitle}". A square comic page with ${args.panels.length} ${panelsWord} ` +
67|    `in ${rows.length} ${rowsWord} (${layout}), read left to right, top to bottom. ` +
68|    args.panels
69|      .map((p, i) => `Panel ${i + 1}: ${clipText(p.description, PANEL_DESC_CHARS)}.`)
70|      .join(" ") +
71|    ` ${styleLine(args.style, args.book)} No text, letters, numbers, captions, sound effects or speech ` +
72|    `balloons anywhere in the image.`
73|  );
74|}

