11|}
12|
13|// Joins one book's two JSON chunks. The import() calls stay inline in
14|// LOADERS below so the bundler sees each book as its own chunk.
15|async function pair(
16|  book: Promise<{ default: unknown }>,
17|  analysis: Promise<{ default: unknown }>,
18|): Promise<BookPayload> {
19|  const [b, a] = await Promise.all([book, analysis]);
20|  return {
21|    book: b.default as BookPayload["book"],
22|    scenes: (a.default as { scenes: AnalyzedScene[] }).scenes,
23|  };
24|}
25|
26|// One lazy entry per processed book: a route loads only its own book,
27|// and unknown ids simply miss the map, so traversal input can never
28|// name a file. One entry per book; the pipeline adds the rest.
29|const LOADERS: Record<string, () => Promise<BookPayload>> = {
30|  oz: () => pair(import("../data/books/oz/book.json"), import("../data/books/oz/analysis.json")),
31|  alice: () =>
32|    pair(import("../data/books/alice/book.json"), import("../data/books/alice/analysis.json")),
33|  carol: () =>
34|    pair(import("../data/books/carol/book.json"), import("../data/books/carol/analysis.json")),
35|  dracula: () =>
36|    pair(import("../data/books/dracula/book.json"), import("../data/books/dracula/analysis.json")),
37|  frankenstein: () =>
38|    pair(
39|      import("../data/books/frankenstein/book.json"),
40|      import("../data/books/frankenstein/analysis.json"),
41|    ),
42|  jungle: () =>
43|    pair(import("../data/books/jungle/book.json"), import("../data/books/jungle/analysis.json")),
44|  peterpan: () =>
45|    pair(
46|      import("../data/books/peterpan/book.json"),
47|      import("../data/books/peterpan/analysis.json"),
48|    ),
49|  pride: () =>
50|    pair(import("../data/books/pride/book.json"), import("../data/books/pride/analysis.json")),
51|  sherlock: () =>
52|    pair(
53|      import("../data/books/sherlock/book.json"),
54|      import("../data/books/sherlock/analysis.json"),
55|    ),
56|  treasure: () =>
57|    pair(
58|      import("../data/books/treasure/book.json"),
59|      import("../data/books/treasure/analysis.json"),
60|    ),
61|};
62|
63|export function isKnownBookId(id: unknown): id is string {
64|  return typeof id === "string" && Object.hasOwn(LOADERS, id);
65|}
66|
67|const readyIds = new Set(library.map((entry) => entry.id));
68|
69|// Known plus listed on the shelf with status ready. The shelf manifest
70|// is the owner's switch: data alone does not publish a book.
71|export function isReadyBookId(id: unknown): boolean {
72|  return isKnownBookId(id) && readyIds.has(id);
73|}
74|
75|export function readyBookIds(): string[] {
76|  return library.map((entry) => entry.id).filter(isKnownBookId);
77|}
78|
79|// Parsed once per book per process; import failures are deterministic
80|// (a missing chunk never heals), so failed loads stay failed.
81|const cache = new Map<string, Promise<BookPayload>>();
82|
83|function readPayload(id: string): Promise<BookPayload> {
84|  const hit = cache.get(id);
85|  if (hit) return hit;
86|  const load = LOADERS[id];
87|  if (!load) notFound();
88|  const pending = load();
89|  cache.set(id, pending);
90|  return pending;
91|}
92|
93|// Processed data for any known id. Chat uses this: a question about a
94|// processed book is answerable whether the shelf lists it or not.
95|// Unknown ids throw notFound() synchronously, before any work starts.
96|// Uploads never load here: chat, pictures, and panels stay shelf-only.
97|export function loadBookData(bookId: string): Promise<BookPayload> {
98|  if (!isKnownBookId(bookId)) notFound();
99|  return readPayload(bookId);
100|}
101|
102|// Shelf books plus finished uploads. Missing, unfinished, or expired
103|// uploads 404 like unknown ids. Uploads bypass the module cache: they
104|// expire after 30 days, so a forever entry would serve a dead book.
105|export function loadBook(bookId: string): Promise<BookPayload> {
106|  if (isUploadId(bookId)) {
107|    return loadUploadedBook(bookId).then((payload) => {
108|      if (!payload) notFound();
109|      return payload;
110|    });
111|  }
112|  if (!isReadyBookId(bookId)) notFound();
113|  return readPayload(bookId);
114|}

